export function computeTotal(items, coupon) {
  let total = 0;
  for (const item of items) {
    if (item.qty > 0) {
      total += item.price * item.qty;
    }
  }
  if (coupon && coupon.percent) {
    total -= total * (coupon.percent / 100);
  }
  return total;
}

